908: int uda_occupy_dev_by_ns(u32 udevid, struct uda_access *access, ka_mnt_namespace_t *ns)
909: {
910:     if (uda_is_dev_shared(udevid)) {
911:         return uda_occupy_shared_dev(udevid, access, ns);
912:     }
913: 
914:     if (access->ns == NULL) {
915:         uda_info("Occupy udevid. (udevid=%u; ns=%pK)\n", udevid, ns);
916:         access->ns = ns; /* set udevid used by this namespace */
917:         return 0;
918:     }
919: 
920:     /* Repeatedly occupied by processes in this namespace */
921:     if (access->ns == ns) {
922:         return 0;
923:     }
924: 
925:     /* The occupied namespace is not alive. Preempt the device. */
926:     if (!uda_dev_is_occupied(access)) {
927:         uda_info("Preempt udevid. (udevid=%u; old_ns=%pK; new_ns=%pK)\n", udevid, access->ns, ns);
928:         access->ns = ns;
929:         return 0;
930:     }
931: 
932:     uda_err("Conflict open udevid. (udevid=%u; access_ns=%pK; ns=%pK)\n", udevid, access->ns, ns);
933:     return -EBUSY;

